"""Exercise the approved-catalog promotion check with real generated bytes, no network."""
import importlib.machinery
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

SCRIPT = Path(__file__).resolve().parents[1] / "scripts/generate-native-catalog.py"
loader = importlib.machinery.SourceFileLoader("native_catalog", str(SCRIPT))
spec = importlib.util.spec_from_loader(loader.name, loader)
catalog = importlib.util.module_from_spec(spec)
loader.exec_module(catalog)

LOCALES = ["en", "vi", "ja", "zh", "zh-Hant"]


def promote(value_by_locale):
    return {"localizations": {
        locale: {"stringUnit": {"state": "translated", "value": text}}
        for locale, text in value_by_locale.items()
    }}


def sign_in(value="Sign in to Atum"):
    return {"en": value, "vi": "Đăng nhập Atum", "ja": "Atum にサインイン",
            "zh": "登录 Atum", "zh-Hant": "登入 Atum"}


class NativeCatalogPromotionTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        root = Path(self.temporary.name)
        self.vendor = root / "vendor"
        self.source = root / "screen-catalog.json"
        self.output = root / "native-catalog.json"
        catalog.VENDOR = self.vendor
        catalog.SOURCE = self.source
        catalog.OUTPUT = self.output

    def promote_source(self, mapping, promoted, copy_proposals, screens=None):
        """Lay out a minimal approved source plus its staged producer map."""
        self.vendor.mkdir()
        (self.vendor / "phone-copy-map.json").write_bytes(json.dumps({
            "schemaVersion": 1, "approvedDesignCommit": "a" * 40,
            "stagingOnly": True, "mapping": mapping}).encode())
        strings = {key: promote(value) for key, value in promoted.items()}
        (self.vendor / "Localizable.xcstrings").write_bytes(json.dumps({
            "sourceLanguage": "vi", "version": "1.0", "strings": strings}).encode())
        (self.vendor / "copy-contract.json").write_bytes(json.dumps({
            "schemaVersion": 1, "parameters": {key: [] for key in strings}}).encode())
        (self.vendor / "manifest.json").write_bytes(json.dumps(
            {"locales": LOCALES}).encode())
        self.source.write_bytes(json.dumps({
            "schemaVersion": 1, "status": "P1 proposal, not gate approval",
            "uiCopy": {}, "source": {"exportsCommit": "b" * 40, "providersCommit": "c" * 40},
            "copyProposals": copy_proposals,
            "screens": screens if screens is not None else [
                {"id": "welcome", "family": "entry", "kind": "welcome",
                 "title": "team.key", "body": "", "rows": [], "inputs": [],
                 "actions": [], "states": []}],
        }).encode())

    def test_mapping_superset_beyond_catalog_promotes(self):
        shell_title = {l: "Không gian nhóm" for l in LOCALES}
        consent = {l: f"Đồng ý {l}" for l in LOCALES}
        self.promote_source(
            mapping={"proposal.1": "team.key", "proposal.245": "shell.teamSpaceTitle",
                     "proposal.275": "shell.signInCloudConsentText"},
            promoted={"team.key": sign_in(), "shell.teamSpaceTitle": shell_title,
                      "shell.signInCloudConsentText": consent},
            copy_proposals={"proposal.1": sign_in()})
        result = json.loads(catalog.generate())
        self.assertEqual(result["approvedDesignCommit"], "a" * 40)
        self.assertEqual(len(result["screens"]), 1)
        self.assertEqual(result["screens"][0]["title"], {"key": "team.key", "arguments": []})
        # Staged shell proposals beyond the catalog never enter its fixture.
        self.assertNotIn("Không gian nhóm", json.dumps(result, ensure_ascii=False))

    def test_catalog_proposal_missing_from_mapping_refused(self):
        self.promote_source(mapping={}, promoted={"team.key": sign_in()},
                            copy_proposals={"proposal.1": sign_in()})
        with self.assertRaises(ValueError) as caught:
            catalog.generate()
        self.assertIn("Approved source proposals missing", str(caught.exception))
        self.assertIn("proposal.1", str(caught.exception))

    def test_promoted_text_drift_refused(self):
        catalog_value = sign_in()
        promoted = dict(catalog_value)
        promoted["en"] = "Sign into Atum"
        self.promote_source(mapping={"proposal.1": "team.key"},
                            promoted={"team.key": promoted},
                            copy_proposals={"proposal.1": catalog_value})
        with self.assertRaises(ValueError) as caught:
            catalog.generate()
        self.assertIn("Proposal text differs", str(caught.exception))

    def test_unpromoted_copy_refused(self):
        shell_title = {l: "Không gian nhóm" for l in LOCALES}
        screen = {"id": "welcome", "family": "entry", "kind": "welcome",
                  "title": "proposal.404", "body": "", "rows": [], "inputs": [],
                  "actions": [], "states": []}
        self.promote_source(mapping={"proposal.1": "team.key",
                                     "proposal.245": "shell.teamSpaceTitle"},
                            promoted={"team.key": sign_in(),
                                      "shell.teamSpaceTitle": shell_title},
                            copy_proposals={"proposal.1": sign_in()}, screens=[screen])
        with self.assertRaises(ValueError) as caught:
            catalog.generate()
        self.assertIn("Unpromoted copy", str(caught.exception))


if __name__ == "__main__":
    unittest.main()
